 "content": "def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    # Color 2 marks background cells bounded by two non-background marks
    # in one row or column; preserve the original non-background marks.
    for r in range(h):
        marks=[c for c in range(w) if grid[r][c]!=bg]
        if len(marks)>1:
            for a,b in zip(marks,marks[1:]):
                if all(grid[r][x]==bg for x in range(a+1,b)):
                    for x in range(a+1,b): out[r][x]=2
    for c in range(w):
        marks=[r for r in range(h) if grid[r][c]!=bg]
        if len(marks)>1:
            for a,b in zip(marks,marks[1:]):
                if all(grid[x][c]==bg for x in range(a+1,b)):
                    for x in range(a+1,b): out[x][c]=2
    return out
